Workaround for me now is patch FormControlName.ngOnDestroy manually.

~~~
export function patchNgFormControlName () {
    return function () {
        const _prototype: any = FormControlName.prototype as any;
        const PATCHED_NAME: string = '__form_control_name_patched';
        
        if (!_prototype[PATCHED_NAME]) {
            const original = _prototype.ngOnDestroy;
            _prototype.ngOnDestroy = function () {
                original && original.apply(this, arguments);
                if (this.control && typeof this.control._clearChangeFns === 'function') {
                    this.control._clearChangeFns();
                }
            };
            _prototype[PATCHED_NAME] = true;
        }
    };
}
~~~
and add the above function as APP_INITIALIZER in app.module

